          groupContext: "人權如今成為普世價值，並藉以衡量一國是否為先進國家。最早的人權思想起源於古希臘、古羅馬、中世紀歐洲的自然法學者著作，但是人權被視為是一個實際問題與理論，則是近代啟蒙運動時所誕生的民主思想。17 世紀英國洛克提出天賦人權，主張人生而自由與平等。法國思想家盧梭根據天賦人權，進一步發展提出社會契約論和人民主權論。1776 年美國〈獨立宣言〉和 1789 年法國〈人權與公民權利宣言〉（簡稱〈人權宣言〉），促使天賦人權從理論轉變為法律。隨著人權的發展，18 世紀末、19 世紀初的邊沁、戴西、彌爾等實證主義與功利主義學者對天賦人權提出批評，認為是達到功利的手段。20 世紀的人權發展為個人權利和政治權利，然而二戰期間人權遭到踐踏，1948 年聯合國通過〈世界人權宣言〉，將人權內容體系化，並成為國際法原則，權利也擴充到經濟社會文化權利；1966 年兩公約更將人權具體化且至強制約束力。聯合國隨後也針對自決權、發展權賦予法源，重視充分多元化以實現人權。",
