          type: "single",
          typeName: "單選題",
          number: 13,
          groupContext: "布拉格的「拋窗事件」，引發一場改變歐洲歷史進程的戰爭——三十年戰爭。\r\n歐洲爆發的三十年戰爭（1618 ～ 1648 年），是由神聖羅馬帝國的內戰演變而成的一場大規模戰爭。肇始於波希米亞人反抗哈布斯堡家族的統治，最後以哈布斯堡家族戰敗並簽訂《西發里亞條約》而告結束。這場戰爭使日耳曼各邦國大約被消滅了 25 ～ 40 個百分比的人口，如路德城維滕貝格四分之三人口陣亡，波美拉尼亞百分之六十五的人口陣亡，西里西亞四分之一的人口陣亡，日耳曼各邦國男性有將近一半陣亡。由於主要戰場在現今的德國，可以說在這場長達三十年的戰爭中，德國的各方面都是飽受摧殘，導致很多的工商、農業受戰爭的影響無法維持和發展，馬克思主義創始人之一恩格斯指出：「三十年戰爭所造成的嚴重後果，使德國有 200 年不見於政治積極的歐洲國家之列。」",
          stem: "在歐洲的歷史發展，現代主權國家在 16 世紀開始形成，背後主因在於封建國家勢力削弱，以及三十年戰爭結束後，各國簽訂《西發里亞條約》，此條約確立何種型態國家的誕生？",
