          number: 18,
          groupContext: "**資料一**：美國政府原本於 2023 年 10 月 1 日要再次重演 2019 年關門的危機，但在期限到期前的幾個小時，當時共和黨籍的眾議院議長麥卡錫提出權宜之計，最終以 335 票比 91 票表決通過暫時資助聯邦政府 45 天。該法案緊接著在參議院又以 88 票對 9 票表決通過。法案內容包括拜登總統提出的救災資金 160 億美元、延長聯邦洪水保險計畫和美國聯邦航空總署重新授權等，但不包括對於烏克蘭的軍事援助。若聯邦政府真的關閉，則超過 400 萬名的美國軍事人員和政府工作人員無法獲得薪酬，被迫放無薪假外，按月領取政府補助的民眾可能也無法因應生活所需。\r\n**資料二**：2018 年美國聯邦政府曾因為預算不足，自 2018 年 12 月 22 日 0 時（北美東部時間）開始，持續至 2019 年 1 月 25 日晚間 9 點半止，歷時 35 天，大約有四分之一的政府活動以及 80 萬名政府員工受到影響。聯邦政府當時停擺的原因在於民主黨控制的眾議院拒絕通過包括美墨邊境圍牆的撥款法案，理由是時任共和黨籍總統川普違背了「建造牆的費用 57 億美元將由墨西哥支付」的競選承諾。然而，川普仍堅持要求眾議院通過修建模擬牆等資金，否則他將否決其他的法案。延至 2019 年 1 月 25 日，川普終於同意通過了一項法案，換取重新開放政府三週，以便繼續進行邊境安全談判。",
