          type: "single",
          typeName: "單選題",
          number: 19,
          groupContext: "每年的 5 月 3 日是「世界新聞自由日」，無國界記者組織（Reporters Without Borders，法語縮寫 RSF）發布《2023 新聞自由指數》（World Press Freedom Index）最新報告。2023 年臺灣在 180 個國家中排名第 35，比去年上升 3 名，是自 2008 年以來的新高。挪威連續第 7 年位居 180 個國家地區榜首，非北歐國家的愛爾蘭則罕見超越丹麥（第 3 名），名列第 2 名；最後 3 名全為亞洲國家，分別是越南（178 名）、被視為全球最大記者監獄與宣傳內容輸出國之一的中國（179 名），以及最後 1 名為北韓（第 180 名）。美國排名下降 3 位至第 45，日本排名上升 3 位至第 68 名，南韓因被認為媒體與企業利益糾纏，未能切實發揮監督作用，排名下滑 4 位至第 47 名。\r\n亞太地區部分，RSF 指出，北韓、中國、越南、緬甸（第 173 名）為亞洲一黨專政國家與獨裁政權，對新聞界壓迫最為嚴重，領導人也持續收緊對公共言論的極權控制。目前中國關押記者人數至少 114 人，甚至包含被控間諜罪的外國記者；緬甸則以微小差距緊追在後，軍方 2021 年發起政變後，緬甸便成為新聞資訊的黑洞。\r\n另外，依據這份報告，中東和北非仍是記者工作最危險的區域，歐洲仍是最安全的地方；臺灣則基本上尊重新聞自由，但記者們受制於一個以煽情與利益為主導的政治兩極化媒體環境，導致民眾對媒體信任度持續下滑。",
