          groupContext: "為了了解我國民眾透過網路進行公民參與的現況及其疑慮，國家發展委員會在 2018 年 8 月公布了一份「2018 年公民網路參與行為調查報告」，其中關於「受訪者居住地的數位發展程度」（一級最高、二級次之，以此類推）及其「在線上公共參與的比例」，如圖(一)所示。\r\n在此調查中也針對參與討論者在進行線上公共參與時，是否會先閱讀、並參考他人發言等經驗進行統計：在發言與閱讀兩個行為的先後次序上，逾六成參與者自認會「看完多數的留言再進行發言」（61.7 %），而「先發言再看其他人的留言」或「發言後就離開，不會閱讀他人留言」則各占 12.5 %，如圖(二)所示。\r\n**圖(一) 數位發展區域之線上公共參與經驗比例**：\r\n- 數位發展一級區域：有參與經驗 37.9% ｜ 無參與經驗 37.0%\r\n- 數位發展二級區域：有參與經驗 41.7% ｜ 無參與經驗 38.8%\r\n- 數位發展三級區域：有參與經驗 14.6% ｜ 無參與經驗 18.2%\r\n- 數位發展四級區域：有參與經驗 4.6% ｜ 無參與經驗 3.0%\r\n- 數位發展五級區域：有參與經驗 1.0% ｜ 無參與經驗 2.8%\r\n**圖(二) 發言與閱讀順序統計**：\r\n- 看完多數留言再發言：61.7%\r\n- 先發言後再閱讀其他留言：12.5%\r\n- 發言後離開，不常閱讀他人留言：12.5%\r\n- 不知道 / 拒答：13.4%",
