          groupContext: "2022 年 11 月 26 日我國舉行九合一大選，期間引發是否讓確診 COVID-19 的民眾投票的爭議。依投票前的確診隔離規定「五＋N」日推算，自 2022 年 11 月 21 日通報確診有投票權的民眾將無法外出投票。指揮中心與中選會皆表示，若確診者外出投票將由衛生單位事後懲處，此規定受到部分學者或媒體等提出質疑，認為若確診者出門投票要重罰，卻沒有其他投票方式，已剝奪人民的參政權，將是「憲政危機」。\r\n反對者指出，「選舉是《憲法》賦予民眾的權利」，雖然現在因疫情特別條例限制民眾投票，仍應有替代方案讓民眾可以參與選舉，否則對民眾權益損害過大。中選會副主委則表示，選務辦理都是依照《傳染病防治法》與《公職人員選舉罷免法》等相關規定，也配合疫情指揮中心防疫政策及措施辦理選務，其餘並無其他評論或回應。儘管衛福部長對此以《憲法》關於限制人民權利之內容作為回應，認為這樣的防疫方針有其依據。然而，有部分人士仍質疑如此限制人民的投票權，恐有違憲之虞。",
