          groupContext: "我國《道路交通管理處罰條例》第 37 條第 3 項規定：計程車駕駛人，在執業期間中，犯竊盜、詐欺、贓物、妨害自由或刑法第 230 條至第 236 條各罪之一（如：妨害風化罪），經第一審法院判決有期徒刑以上之判決後，吊扣其執業登記證。其經法院判決有期徒刑以上之刑確定者，廢止其執業登記，並吊銷其駕駛執照。\r\n在經過相關人等聲請釋憲後，民國 106 年 6 月，大法官做出釋字第 749 號，有關「吊扣或廢止執業登記」部分，大法官認為僅以計程車駕駛人所觸犯之罪及經法院判決有期徒刑以上之刑為要件，而不問其犯行是否足以顯示對乘客安全具有實質風險，均吊扣其執業登記證、廢止其執業登記，就此而言，已違反(甲)原則，亦與《憲法》保障人民之(乙)意旨有違。\r\n有關吊銷駕駛執照部分，顯逾達成定期禁業目的之必要程度，不符憲法所規範的原則，且與其所保障的基本權利相違背，應自本解釋公布之日起失其效力。",
